<script setup>
import { computed, onMounted, onUnmounted, ref } from 'vue'
import { submitRequest } from './lib/supabase'

const modal = ref(false), payment = ref(false), sent = ref(false), sending = ref(false), step = ref(0)
const files = ref([])
const form = ref({ first_name:'', last_name:'', phone:'', address:'', service:'Impression simple', service_option:'', delivery_method:'Livraison', payment_method:'Orange Money' })
const services = [
  ['Montage affiche', 'A5, A4, A3, A2, A1 ou réseaux sociaux'], ['Montage banderole', '2 m × 80, 4 m × 80, 6 m × 80'],
  ['Montage + impression', 'Affiche prête à faire vivre'], ['Impression simple', 'Documents, images et supports'],
  ['Impression + reliure simple', 'Vos dossiers, parfaitement assemblés'], ['Impression + reliure à chaud', 'Une finition professionnelle'],
  ['Impression + encollage', 'Pour vos supports élégants'], ['Montage vidéo simple', 'Stories, films et souvenirs'],
  ['Montage vidéo + gravure CD', 'Du montage au support final'], ['Montage audio', 'Un son net et maîtrisé'],
  ['Gravure CD', 'Vos fichiers sur support physique'], ['Confection d’invitations', 'Pour marquer vos événements'],
  ['Motion design', 'Des idées qui prennent vie'], ['Confection de logos', 'Une identité qui vous ressemble']
]
const formats = ['A5','A4','A3','A2','A1','Facebook','WhatsApp statuts','Instagram','LinkedIn']
const durations = ['5 minutes','10 minutes','15 minutes','20 minutes','30 minutes','Plus de 30 minutes']
const options = computed(() => form.value.service.includes('vidéo') || form.value.service === 'Montage audio' ? durations : form.value.service === 'Montage banderole' ? ['2 m × 80','4 m × 80','6 m × 80'] : ['Gravure CD','Confection d’invitations','Motion design','Confection de logos'].includes(form.value.service) ? [] : formats)
const total = computed(() => form.value.delivery_method === 'Livraison' ? '2 500 FCFA' : '0 FCFA')
function openForm() { modal.value = true; payment.value = false; sent.value = false }
function chooseService(name) { form.value.service = name; form.value.service_option = ''; openForm() }
function scrollProgress() { const hero = document.querySelector('.flow-area'); if (!hero) return; const p = Math.max(0, Math.min(1, -hero.getBoundingClientRect().top / (hero.offsetHeight - innerHeight))); step.value = Math.min(4, Math.floor(p * 5.3)) }
async function continuePayment() { if (!form.value.first_name || !form.value.last_name || !form.value.phone) return; payment.value = true }
async function send() { sending.value = true; try { await submitRequest({ ...form.value, payment_status:'pending', total: form.value.delivery_method === 'Livraison' ? 2500 : 0 }, files.value); sent.value = true } catch (e) { alert('Une erreur est survenue. Vérifiez votre connexion Supabase.'); console.error(e) } finally { sending.value = false } }
onMounted(() => addEventListener('scroll', scrollProgress, { passive:true }))
onUnmounted(() => removeEventListener('scroll', scrollProgress))
</script>

<template>
  <header><a class="brand" href="#top"><span>atelier</span>print<span class="dot">.</span></a><nav><a href="#services">Services</a><a href="#tarifs">Tarifs</a><a href="#process">Comment ça marche</a></nav><button class="header-cta" @click="openForm">Envoyer mes fichiers <b>↗</b></button></header>
  <main id="top">
    <section class="intro"><p class="eyebrow">IMPRESSION &amp; CRÉATION — ABIDJAN</p><h1>Vos idées méritent<br><i>de prendre forme.</i></h1><p class="lede">Imprimez, créez et recevez. De votre écran à vos mains, nous orchestrons chaque détail.</p><button class="primary" @click="openForm">Démarrer un projet <span>→</span></button><div class="scroll-hint">DÉFILEZ POUR DÉCOUVRIR <span>↓</span></div></section>
    <section id="process" class="flow-area"><div class="flow-sticky"><div class="flow-copy"><p class="eyebrow">DE L’IDÉE À LA MAIN</p><h2 v-if="step===0">Déposez vos<br><i>fichiers.</i></h2><h2 v-else-if="step===1">Un clic, et c’est<br><i>parti.</i></h2><h2 v-else-if="step===2">Vos fichiers voyagent<br><i>en toute sécurité.</i></h2><h2 v-else-if="step===3">La machine donne<br><i>vie à vos pages.</i></h2><h2 v-else>Votre projet arrive<br><i>chez vous.</i></h2><p>{{ ['Tout commence ici. Envoyez-nous vos fichiers, quel que soit leur format.', 'Simple, rapide, sans aller-retour. Nous recevons votre demande instantanément.', 'Notre équipe vérifie votre document avant de l’envoyer en production.', 'Couleurs éclatantes, finitions soignées : votre support est imprimé avec attention.', 'Récupérez votre commande à l’atelier ou choisissez la livraison.'][step] }}</p></div><div class="scene" :class="'scene-'+step"><div class="progress"><b v-for="n in 5" :class="{active:n<=step+1}" :key="n"></b></div><div class="computer"><div class="screen"><span class="ui-title">atelierprint</span><div class="file-card"><span class="file-icon">✦</span><b>Mon_projet.pdf</b><small>24.8 MB · Prêt à envoyer</small><button>Envoyer les fichiers <span>→</span></button></div></div><div class="stand"></div></div><div class="server">☁<small>NOS SERVEURS</small></div><div class="printer"><div class="printer-top"></div><div class="printer-body"><span>atelierprint</span><i></i></div><div class="book">VOTRE<br>HISTOIRE</div></div><div class="van">●<span>atelier<br>print</span><b>●</b></div></div></div></section>
    <section id="services" class="services"><div class="section-head"><p class="eyebrow">CE QUE NOUS FAISONS</p><h2>Un atelier, <i>mille possibilités.</i></h2><p>De la première idée au dernier détail, une équipe pour faire exister tous vos projets.</p></div><div class="service-grid"><button v-for="(s,i) in services" :key="s[0]" class="service-card" @click="chooseService(s[0])"><span>0{{i+1}}</span><h3>{{s[0]}}</h3><p>{{s[1]}}</p><b>↗</b></button></div></section>
    <section id="tarifs" class="pricing"><div><p class="eyebrow">NOS TARIFS</p><h2>Des prix clairs,<br><i>sans surprise.</i></h2><p>Le devis final dépend de votre projet. Les frais de livraison sont indiqués avant paiement.</p><button class="outline" @click="openForm">Demander un devis →</button></div><div class="price-list"><div><span>Impression couleur</span><b>à partir de 100 FCFA</b></div><div><span>Montage affiche</span><b>à partir de 5 000 FCFA</b></div><div><span>Montage vidéo</span><b>à partir de 15 000 FCFA</b></div><div><span>Confection de logo</span><b>à partir de 20 000 FCFA</b></div><div><span>Livraison</span><b>à partir de 2 500 FCFA</b></div></div></section>
    <section class="closing"><p class="eyebrow">UN PROJET EN TÊTE ?</p><h2>Faisons-le <i>exister.</i></h2><button class="primary light" @click="openForm">Envoyer mes fichiers <span>→</span></button></section>
  </main><footer><a class="brand"><span>atelier</span>print<span class="dot">.</span></a><p>Création, impression &amp; livraison.<br>Fait avec soin à Abidjan.</p><span>© 2026 ATELIERPRINT</span></footer>
  <Teleport to="body"><div v-if="modal" class="modal-backdrop" @click.self="modal=false"><section class="modal"><button class="close" @click="modal=false">×</button><template v-if="sent"><div class="sent"><span>✓</span><p class="eyebrow">DEMANDE ENVOYÉE</p><h2>Merci, {{form.first_name}} !</h2><p>Votre demande est bien arrivée à l’atelier. Nous vous recontactons rapidement pour finaliser votre commande.</p><button class="primary" @click="modal=false">Fermer</button></div></template><template v-else-if="!payment"><p class="eyebrow">VOTRE PROJET</p><h2>Envoyez vos fichiers.</h2><p class="modal-sub">Tous les formats sont les bienvenus : documents, images, vidéos et audios.</p><div class="form-grid"><label>Prénom<input v-model="form.first_name" placeholder="Votre prénom"></label><label>Nom<input v-model="form.last_name" placeholder="Votre nom"></label><label>Numéro de téléphone<input v-model="form.phone" placeholder="+225 00 00 00 00"></label><label>Adresse<input v-model="form.address" placeholder="Votre adresse"></label><label>Service<select v-model="form.service"><option v-for="s in services" :key="s[0]">{{s[0]}}</option></select></label><label v-if="options.length">Format / option<select v-model="form.service_option"><option value="">Choisir</option><option v-for="option in options">{{option}}</option></select></label></div><label class="upload"> <input type="file" multiple accept="image/*,video/*,audio/*,.pdf,.doc,.docx" @change="files=$event.target.files"><span>＋</span><b>{{ files.length ? files.length + ' fichier(s) sélectionné(s)' : 'Ajouter un ou plusieurs fichiers' }}</b><small>PDF, DOC, JPG, PNG, MP4, MP3...</small></label><div class="delivery"><b>Comment souhaitez-vous recevoir votre commande ?</b><label><input type="radio" v-model="form.delivery_method" value="Livraison"> Livraison <small>+ 2 500 FCFA</small></label><label><input type="radio" v-model="form.delivery_method" value="Retrait en atelier"> Retrait à l’atelier <small>Gratuit</small></label></div><button class="primary submit" @click="continuePayment">Continuer vers le paiement <span>→</span></button></template><template v-else><p class="eyebrow">ÉTAPE FINALE</p><h2>Choisissez votre paiement.</h2><p class="modal-sub">Les frais de livraison estimés sont de <b>{{total}}</b>.</p><div class="payments"><label><input type="radio" v-model="form.payment_method" value="Orange Money"><span class="orange">OM</span> Orange Money</label><label><input type="radio" v-model="form.payment_method" value="MTN Mobile Money"><span class="mtn">MoMo</span> MTN Mobile Money</label><label><input type="radio" v-model="form.payment_method" value="Cash"><span class="cash">¤</span> Cash à la {{form.delivery_method === 'Livraison' ? 'livraison' : 'récupération'}}</label></div><button class="primary submit" :disabled="sending" @click="send">{{ sending ? 'Envoi en cours...' : 'Envoyer ma demande →' }}</button><button class="back" @click="payment=false">← Modifier ma demande</button></template></section></div></Teleport>
</template>
